import type { LanguageSlug } from "@/app/lib/language-content";
import { educationalSources } from "@/app/lib/content-sources";
import type { GrammarExerciseType, GrammarTopic } from "@/app/lib/grammar-content";

type QuestionSeed = {
  type: GrammarExerciseType;
  instruction: string;
  prompt: string;
  answer: string;
  acceptedAnswers?: string[];
  options?: string[];
  explanation: string;
  distractorExplanations?: Record<string, string>;
};

type LessonSeed = Omit<GrammarTopic, "id" | "exercises" | "sourceIds" | "verification"> & {
  questions: [QuestionSeed, QuestionSeed, QuestionSeed];
};

const sourceMap: Record<LanguageSlug, string[]> = {
  english: ["cefr-companion-volume", "cambridge-english-cefr", "british-council-grammar"],
  french: ["cefr-companion-volume", "delf-fei", "tv5monde-edu"],
  spanish: ["cefr-companion-volume", "rae-grammar", "spanish-dele-cervantes"],
  italian: ["cefr-companion-volume", "cils-siena", "italian-certification-dante"],
  german: ["cefr-companion-volume", "dw-learn-german", "goethe-exams", "telc-certificate-exams"],
};

function slugify(value: string) {
  return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ß/g, "ss")
    .toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
}

function lesson(seed: LessonSeed): GrammarTopic {
  const topicId = `${seed.language}-${seed.level}-${slugify(seed.title)}`;
  const questions = seed.questions.map((question, index) => ({
    id: `${topicId}-exercise-${index + 1}`,
    topicId,
    level: seed.level,
    type: question.type,
    prompt: question.prompt,
    instruction: question.instruction,
    options: question.options,
    acceptedAnswers: question.acceptedAnswers ?? [question.answer],
    explanation: question.explanation,
    distractorExplanations: question.distractorExplanations,
    isFinalQuiz: index === 2,
  }));
  return {
    ...seed,
    id: topicId,
    exercises: questions,
    sourceIds: sourceMap[seed.language],
    verification: "original-sample-needs-teacher-review",
  };
}

